// Package argparse is a minimal command-line argument parser.
package argparse

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
	"text/tabwriter"
)

// ErrHelp is returned by Parse when -h or --help is given.
var ErrHelp = errors.New("help requested")

type flag struct {
	name  string
	short byte // 0 for none
	usage string
	def   string
	b     *bool // non-nil for boolean flags
	s     *string
}

type positional struct {
	name, usage string
	value       *string
}

type Parser struct {
	name, desc string
	flags      []*flag
	pos        []*positional
}

func New(name, desc string) *Parser {
	return &Parser{name: name, desc: desc}
}

// Bool defines a boolean flag. Pass 0 as short for a long-only flag.
func (p *Parser) Bool(name string, short byte, usage string) *bool {
	b := new(bool)
	p.flags = append(p.flags, &flag{name: name, short: short, usage: usage, b: b})
	return b
}

// String defines a flag that takes a value.
func (p *Parser) String(name string, short byte, def, usage string) *string {
	s := new(string)
	*s = def
	p.flags = append(p.flags, &flag{name: name, short: short, usage: usage, def: def, s: s})
	return s
}

// Arg defines a required positional argument, filled in definition order.
func (p *Parser) Arg(name, usage string) *string {
	s := new(string)
	p.pos = append(p.pos, &positional{name, usage, s})
	return s
}

func (p *Parser) lookup(name string, long bool) *flag {
	for _, f := range p.flags {
		if long && f.name == name || !long && len(name) == 1 && f.short == name[0] {
			return f
		}
	}
	return nil
}

// Parse parses args (usually os.Args[1:]) and returns the positional
// arguments left over after the ones defined with Arg. Everything after
// a bare "--" is treated as positional.
func (p *Parser) Parse(args []string) ([]string, error) {
	var rest []string
	for i := 0; i < len(args); i++ {
		a := args[i]
		if a == "--" {
			rest = append(rest, args[i+1:]...)
			break
		}
		if len(a) < 2 || a[0] != '-' {
			rest = append(rest, a)
			continue
		}
		long := strings.HasPrefix(a, "--")
		name, val, hasVal := strings.Cut(strings.TrimPrefix(a[1:], "-"), "=")
		f := p.lookup(name, long)
		switch {
		case f == nil && (long && name == "help" || !long && name == "h"):
			return nil, ErrHelp
		case f == nil:
			return nil, fmt.Errorf("unknown flag: %s", a)
		case f.b != nil:
			*f.b = true
			if hasVal {
				v, err := strconv.ParseBool(val)
				if err != nil {
					return nil, fmt.Errorf("invalid boolean for --%s: %q", f.name, val)
				}
				*f.b = v
			}
		default:
			if !hasVal {
				if i++; i >= len(args) {
					return nil, fmt.Errorf("flag needs a value: %s", a)
				}
				val = args[i]
			}
			*f.s = val
		}
	}
	if len(rest) < len(p.pos) {
		return nil, fmt.Errorf("missing argument: <%s>", p.pos[len(rest)].name)
	}
	for i, a := range p.pos {
		*a.value = rest[i]
	}
	return rest[len(p.pos):], nil
}

// Usage returns the help message generated from the definitions.
func (p *Parser) Usage() string {
	var sb strings.Builder
	fmt.Fprintf(&sb, "Usage: %s [flags]", p.name)
	for _, a := range p.pos {
		fmt.Fprintf(&sb, " <%s>", a.name)
	}
	sb.WriteString("\n")
	if p.desc != "" {
		fmt.Fprintf(&sb, "\n%s\n", p.desc)
	}
	w := tabwriter.NewWriter(&sb, 0, 0, 2, ' ', 0)
	if len(p.pos) > 0 {
		fmt.Fprintln(w, "\nArguments:")
		for _, a := range p.pos {
			fmt.Fprintf(w, "  %s\t%s\n", a.name, a.usage)
		}
	}
	fmt.Fprintln(w, "\nFlags:")
	row := func(short byte, name, kind, usage string) {
		s := "    "
		if short != 0 {
			s = "-" + string(short) + ", "
		}
		fmt.Fprintf(w, "  %s--%s%s\t%s\n", s, name, kind, usage)
	}
	for _, f := range p.flags {
		kind, usage := "", f.usage
		if f.b == nil {
			kind = " <value>"
			if f.def != "" {
				usage += fmt.Sprintf(" (default %q)", f.def)
			}
		}
		row(f.short, f.name, kind, usage)
	}
	row('h', "help", "", "show this help")
	w.Flush()
	return sb.String()
}
