package argparse

import (
	"errors"
	"reflect"
	"strings"
	"testing"
)

func setup() (*Parser, *bool, *string, *string) {
	p := New("cp", "Copy a file.")
	v := p.Bool("verbose", 'v', "print progress")
	m := p.String("mode", 'm', "0644", "file mode")
	src := p.Arg("src", "source file")
	return p, v, m, src
}

func TestParse(t *testing.T) {
	for _, args := range [][]string{
		{"-v", "--mode=0600", "a", "b", "c"},
		{"a", "--verbose", "-m", "0600", "b", "c"},
		{"--verbose=true", "-m=0600", "a", "--", "b", "c"},
	} {
		p, v, m, src := setup()
		rest, err := p.Parse(args)
		if err != nil || !*v || *m != "0600" || *src != "a" || !reflect.DeepEqual(rest, []string{"b", "c"}) {
			t.Errorf("%v: v=%v m=%q src=%q rest=%v err=%v", args, *v, *m, *src, rest, err)
		}
	}

	p, v, m, _ := setup()
	rest, err := p.Parse([]string{"--", "-v"})
	if err != nil || *v || *m != "0644" || len(rest) != 0 {
		t.Errorf("defaults/--: v=%v m=%q rest=%v err=%v", *v, *m, rest, err)
	}
}

func TestErrors(t *testing.T) {
	for args, want := range map[string]string{
		"--nope a":      "unknown flag",
		"a -m":          "needs a value",
		"-v":            "missing argument: <src>",
		"--verbose=x a": "invalid boolean",
	} {
		p, _, _, _ := setup()
		if _, err := p.Parse(strings.Fields(args)); err == nil || !strings.Contains(err.Error(), want) {
			t.Errorf("%q: got %v, want %q", args, err, want)
		}
	}
	p, _, _, _ := setup()
	if _, err := p.Parse([]string{"-h"}); !errors.Is(err, ErrHelp) {
		t.Errorf("-h: got %v", err)
	}
}

func TestUsage(t *testing.T) {
	p, _, _, _ := setup()
	u := p.Usage()
	for _, want := range []string{"Usage: cp [flags] <src>", "-v, --verbose", `-m, --mode <value>  file mode (default "0644")`, "-h, --help"} {
		if !strings.Contains(u, want) {
			t.Errorf("usage missing %q:\n%s", want, u)
		}
	}
	t.Log("\n" + u)
}
